const SMART_PLAN_EVENT_DB_COLUMNS=new Set(['id','client_event_id','plan_id','student_id','event_type','event_date','payload','created_by','created_at']);
function cleanSmartPlanEventRow(row){let out={};for(let [key,value] of Object.entries(row||{}))if(SMART_PLAN_EVENT_DB_COLUMNS.has(key))out[key]=value;return out}
function normalizeSmartPlanRequestedPages(value,{writeBack=false}={}){let n=Number(value);if(!Number.isFinite(n)||n<=0)return 0;let rounded=Math.min(604,Math.max(1,Math.ceil(n-1e-9)));if(writeBack&&$('#spHifzTargetPages'))$('#spHifzTargetPages').value=String(rounded);return rounded}
window.normalizeSmartPlanRequestedPages=normalizeSmartPlanRequestedPages;
async function applySmartPlanOfflineOperation(op){
  if(op.type==='smart_plan_upsert'){
    let mode=op.payload?.mode||'update',obj=cleanSmartPlanRow(op.payload?.row||op.payload||op.obj||{}),result;
    if(mode==='insert'){
      result=await db.from('smart_plans').insert(obj).select().single();
      if(result.error&&String(result.error.code)==='23505')result=await db.from('smart_plans').select('*').eq('id',obj.id).single()
    }else result=await db.from('smart_plans').update(obj).eq('id',obj.id).select().single();
    if(result.error)throw result.error;
    let index=state.smartPlans.findIndex(x=>x.id===result.data.id);if(index>=0)state.smartPlans[index]=result.data;else state.smartPlans.push(result.data);return
  }
  if(op.type==='smart_plan_event'){
    let obj=cleanSmartPlanEventRow(op.payload||{}),result=await db.from('smart_plan_events').insert(obj).select().single();if(result.error&&String(result.error.code)!=='23505')throw result.error;
    let saved=result.data||obj,index=state.smartPlanEvents.findIndex(x=>x.client_event_id===saved.client_event_id);if(index>=0)state.smartPlanEvents[index]=saved;else state.smartPlanEvents.push(saved);return
  }
  if(op.type==='smart_plan_delete'){
    let id=String(op.payload?.id||op.id||'');if(!id)return;let result=await db.from('smart_plans').delete().eq('id',id).select('id');if(result.error)throw result.error;state.smartPlans=state.smartPlans.filter(x=>x.id!==id);state.smartPlanEvents=state.smartPlanEvents.filter(x=>x.plan_id!==id);return
  }
}
const smartPlanBaseApplyOfflineOperation=applyOfflineOperation;
applyOfflineOperation=async function(op,map){if(['smart_plan_upsert','smart_plan_event','smart_plan_delete'].includes(op.type))return await applySmartPlanOfflineOperation(op,map);return await smartPlanBaseApplyOfflineOperation(op,map)};
const smartPlanBaseSyncOperationLabel=syncOperationLabel;
syncOperationLabel=function(op){if(op.type==='smart_plan_upsert')return 'خطة ذكية';if(op.type==='smart_plan_event')return 'حدث خطة ذكية';if(op.type==='smart_plan_delete')return 'حذف خطة مؤرشفة';return smartPlanBaseSyncOperationLabel(op)};
const smartPlanBaseOfflinePriority=offlineOperationPriority;
offlineOperationPriority=function(op){if(op.type==='smart_plan_delete')return 34;if(op.type==='smart_plan_upsert')return 35;if(op.type==='smart_plan_event')return 55;return smartPlanBaseOfflinePriority(op)};

function saveSmartPlanLocal(plan,{announce=true}={}){
  let index=state.smartPlans.findIndex(x=>x.id===plan.id),previous=index>=0?state.smartPlans[index]:null,mode=previous?._syncMode||(!previous?'insert':'update'),local={...plan,_offline:true,_syncMode:mode};if(index>=0)state.smartPlans[index]=local;else state.smartPlans.unshift(local);
  enqueueOffline({type:'smart_plan_upsert',key:`smart-plan:${plan.id}`,dedupeKey:`smart-plan:${plan.id}`,payload:{mode,row:cleanSmartPlanRow(plan)}});if(announce)toast('تم حفظ الخطة محلياً وستتزامن تلقائياً');if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),40)
}
function recordSmartPlanEvent(planId,studentId,eventType,payload={}){
  let event={id:offlineUuid(),client_event_id:offlineUuid(),plan_id:planId,student_id:studentId,event_type:eventType,event_date:today(),payload,created_by:state.user.id,created_at:new Date().toISOString(),_offline:true};state.smartPlanEvents.unshift(event);enqueueOffline({type:'smart_plan_event',key:`smart-plan-event:${event.client_event_id}`,dedupeKey:`smart-plan-event:${event.client_event_id}`,payload:cleanSmartPlanEventRow(event)});return event
}

async function runSmartPlanAutoExtensions(){
  if(state.smartPlanAutomationRunning||!roleCanManage()||!state.smartPlansAvailable)return;state.smartPlanAutomationRunning=true;
  try{
    for(let plan of (state.smartPlans||[]).filter(x=>x.status==='active'&&x.auto_extend!==false)){
      let updates=activeSmartPlanStudents(plan).map(student=>({student,progress:smartPlanProgress(plan,student.id)})).filter(x=>x.progress.extensionNeeded);
      if(!updates.length)continue;let nextEnd=updates.map(x=>x.progress.suggestedEndDate).sort().at(-1);if(!nextEnd||nextEnd<=plan.end_date)continue;
      let previous=plan.end_date,updated={...plan,end_date:nextEnd,updated_at:new Date().toISOString()};saveSmartPlanLocal(updated,{announce:false});for(let item of updates)recordSmartPlanEvent(plan.id,item.student.id,'auto_extension',{old_end_date:previous,new_end_date:nextEnd,uncovered_deficit:item.progress.deficit})
    }
  }finally{state.smartPlanAutomationRunning=false}
}

function smartPlanRouteSteps(plan){
  if(!['hifz','sard','tathbit'].includes(plan?.plan_type)||!Number(plan.range_start_surah)||!Number(plan.range_end_surah))return [];
  let direction=plan.plan_type==='hifz'?'reverse_surahs_forward_ayahs':plan.settings?.route_direction||'forward_surahs_forward_ayahs',key=smartPlanMemoKey(plan.plan_type,plan.range_start_surah,plan.range_start_ayah,plan.range_end_surah,plan.range_end_ayah,direction);
  if(smartPlanRenderMemo.active&&smartPlanRenderMemo.routeSteps.has(key))return smartPlanRenderMemo.routeSteps.get(key);
  let steps=buildDirectionalRangeToEnd(plan.range_start_surah,plan.range_start_ayah,plan.range_end_surah,plan.range_end_ayah,direction)?.steps||[];
  if(smartPlanRenderMemo.active)smartPlanRenderMemo.routeSteps.set(key,steps);
  return steps
}
function smartPlanSegmentsFromSteps(steps=[]){let segments=[];for(let step of steps){let last=segments.at(-1);if(last&&last.surah===step.surah&&step.ayah===last.endAyah+1)last.endAyah=step.ayah;else segments.push({surah:step.surah,startAyah:step.ayah,endAyah:step.ayah})}return segments}
function smartPlanSegmentsText(segments=[]){return segments.map(seg=>`${surahs[seg.surah-1]} ${seg.endAyah!==seg.startAyah?`من ${fmt(seg.startAyah)} إلى ${fmt(seg.endAyah)}`:fmt(seg.startAyah)}`).join('، ')||'—'}
function smartPlanPlanRangeText(plan){if(['hifz','sard','tathbit'].includes(plan?.plan_type)&&Number(plan.range_start_surah)&&Number(plan.range_end_surah)){let arrow=plan.settings?.route_direction==='forward_surahs_forward_ayahs'?'→':'←';return `${smartPlanHifzPointText({surah:plan.range_start_surah,ayah:plan.range_start_ayah})} ${arrow} ${smartPlanHifzPointText({surah:plan.range_end_surah,ayah:plan.range_end_ayah})}`}return smartPlanRangeText(plan?.range_start_page,plan?.range_end_page)}
function smartPlanAcceptedAyahRanges(plan,studentId,date){
  if(plan.plan_type!=='hifz'||!studentId)return [];
  return smartPlanStudentRecitations(studentId).filter(r=>['new_hifz','hifz'].includes(r.activity_type)&&smartPlanDateOfRecord(r)<=date&&Number(r.start_surah)&&Number(r.end_surah)&&Number(r.start_ayah)&&Number(r.end_ayah)&&smartPlansEngine.isPassing(r,plan)).map(r=>({start:smartPlanHifzCursorScore(r.start_surah,r.start_ayah),end:smartPlanHifzCursorScore(r.end_surah,r.end_ayah)})).filter(r=>r.end>=r.start);
}
function decorateSmartPlanAssignment(plan,progress,studentId=null,date=today()){let base=progress?.assignment||{};if(!['hifz','sard','tathbit'].includes(plan?.plan_type)||!progress?.linePlan||base.milestone)return base;let scheduledPages=Number(base.pages||0);
  /* v2.19.3: on non-scheduled days the engine intentionally returns 0 pages.
     Do not manufacture a one-ayah assignment by picking the first unfinished step. */
  if(!base.blockedByRetry&&scheduledPages<=0.001)return {...base,ayahSegments:[],ayahLabel:'',scheduledPages:base.pages,startPage:null,endPage:null};
  let steps=smartPlanRouteSteps(plan),wanted=new Set(base.blockedByRetry?(progress.retryLineKeys||[]):[]),completed=new Set(progress.completedLineKeys||[]),picked=[],lineSet=new Set(),needed=Math.max(0,Math.ceil(scheduledPages*15));
  let accepted=base.blockedByRetry?[]:smartPlanAcceptedAyahRanges(plan,studentId,date);
  let allowed=new Set(plan.settings?.memorization_line_keys||steps.flatMap(step=>step.lineKeys||[]));
  for(let step of steps){let point=smartPlanHifzCursorScore(step.surah,step.ayah);if(accepted.some(r=>point>=r.start&&point<=r.end))continue;let keys=(step.allLineKeys?.length?step.allLineKeys:step.lineKeys||[]).filter(k=>allowed.has(k)),relevant=base.blockedByRetry?keys.some(k=>wanted.has(k)):keys.some(k=>!completed.has(k));if(!relevant)continue;picked.push(step);for(let key of keys){if(base.blockedByRetry?!wanted.has(key):completed.has(key))continue;lineSet.add(key)}if(!base.blockedByRetry&&lineSet.size>=needed)break}
  let segments=smartPlanSegmentsFromSteps(picked),pages=Math.round((lineSet.size/15)*100)/100;return {...base,ayahSegments:segments,ayahLabel:smartPlanSegmentsText(segments),pages,scheduledPages:base.pages,startPage:picked[0]?.page||null,endPage:picked.at(-1)?.page||null}
}
function smartPlanRangeText(start,end){if(!start)return 'لا يوجد مقدار اليوم';return start===end?`صفحة ${fmt(start)}`:`الصفحات من ${fmt(start)} إلى ${fmt(end)}`}
function smartPlanRangesText(ranges=[]){return ranges.map(x=>x.start===x.end?fmt(x.start):`${fmt(x.start)}–${fmt(x.end)}`).join('، ')||'—'}
function smartPlanAssignmentLabel(assignment){if(!assignment)return 'لا يوجد مقرر';let kind={hifz:'حفظ',review:'مراجعة',sard:'سرد',tathbit:'إعادة الحفظ السابق',test:'اختبار مرحلي'}[assignment.kind]||'مقرر';return `${kind}: ${assignment.ayahLabel||smartPlanRangeText(assignment.startPage,assignment.endPage)}`}
