function smartPlanLastRecitationHtml(student,plan){let r=smartPlanLastRecitation(student,plan);if(!r)return '<div class="smart-last-rec"><b>🕘 آخر تسميع</b><span>لا يوجد تسميع سابق لهذا المسار.</span></div>';let ev=evalAr[r.evaluation]||r.evaluation||r.rating||'—';return `<div class="smart-last-rec"><b>🕘 آخر تسميع · ${esc(smartPlanDateOfRecord(r)||'—')}</b><span>${esc(smartPlanRecitationRangeText(r))} · ${fmt(r.pages_count)} ص</span><span>⭐ ${esc(ev)} · ❌ ${r.mistakes||0} خطأ · 👆 ${r.prompts||0} نقرة</span></div>`}
