function smartPlanGuardianStatusText(progress,required,done){if(progress.pauseReason==='sard_week')return 'أسبوع السرد — الحفظ الجديد متوقف اليوم';if(progress.remaining<=0)return 'تم إنجاز الخطة';if(required<=0)return 'لا يوجد مقرر لهذا المسار اليوم';if(done+0.001>=required)return done>required+0.001?`تم المطلوب وزاد ${fmt(done-required)} ص`:'تم المطلوب اليوم';let recovery=Number(progress.recoveryShare||0);return recovery>0?`متبقي ${fmt(Math.max(0,required-done))} ص اليوم · منها ${fmt(recovery)} ص تعويض`:`متبقي ${fmt(Math.max(0,required-done))} ص اليوم`}
function smartPlanGuardianCompactPanel(student,date=today()){let plans=effectiveSmartPlans(student,date);if(!plans.length)return '<div class="guardian-plan-simple empty">لا توجد خطة فعالة اليوم.</div>';return `<div class="guardian-plan-simple"><div class="guardian-plan-head"><b>🧭 خطة اليوم</b><span>${esc(student.full_name)}</span></div>${plans.map(plan=>{let p=smartPlanProgress(plan,student.id,date),a=p.assignment,done=Number(p.completedToday||0),required=Number(p.dailyTarget??a.pages??0),next=smartPlanNextDuty(plan,student,date),last=smartPlanLastRecitation(student,plan),ev=last?(evalAr[last.evaluation]||last.evaluation||last.rating||'—'):'—',icon=plan.plan_type==='sard'?'🔁':plan.plan_type==='tathbit'?'🧩':plan.plan_type==='review'?'🔄':'📖';return `<div class="guardian-plan-row"><div class="guardian-plan-title"><b>${icon} ${smartPlanTypeAr[plan.plan_type]}</b><span>${esc(smartPlanGuardianStatusText(p,required,done))}</span></div><div class="guardian-plan-grid"><span><small>مطلوب اليوم</small><b>${required>0?smartPlanAssignmentLabel(a):'لا يوجد'}</b></span><span><small>أنجز اليوم</small><b>${fmt(done)} ص</b></span>${last?`<span><small>آخر تسميع · ${esc(smartPlanDateOfRecord(last))}</small><b>${esc(smartPlanRecitationRangeText(last))}</b><em>${esc(ev)} · ${last.mistakes||0} خطأ · ${last.prompts||0} نقرة</em></span>`:''}${next?`<span><small>المقرر القادم · ${esc(next.date)}</small><b>${smartPlanAssignmentLabel(next.progress.assignment)}</b></span>`:''}</div></div>`}).join('')}</div>`}
function guardianLatestActivityHtml(student){let item=state.guardianActivities?.[String(student.id)]||state.guardianActivities?.[student.id];if(!item?.session)return '';let se=item.session,n=item.note||{},d=se.activity_data||{},score=Number(n.activity_max_score||0)>0?`${fmt(n.activity_score||0)} / ${fmt(n.activity_max_score)}`:'',part=n.participation==='excellent'?'مميز':n.participation==='good'?'جيد':'عادي';return `<div class="guardian-activity-card"><div><b>🌱 آخر لقاء تربوي</b><span>${esc(se.session_date)}${se.title?` · ${esc(se.title)}`:''}</span></div>${d.weekly_value?`<span><small>قيمة اللقاء</small><b>${esc(d.weekly_value)}</b></span>`:''}${d.summary?`<p>${esc(d.summary)}</p>`:''}<div class="guardian-activity-meta">${score?`<span>🏆 ${score}</span>`:''}<span>⭐ التفاعل: ${esc(part)}</span></div></div>`}
function smartPlanStudentPanel(student,date=today(),compact=false){
  if(compact)return smartPlanGuardianCompactPanel(student,date);let plans=effectiveSmartPlans(student,date);if(!plans.length)return `<div class="card smart-student-plan"><div class="section-head"><h3>الخطة الذكية</h3>${roleCanManage()?`<button class="mini" onclick="openPlan('${student.id}')">+ إنشاء مسار</button>`:''}</div><div class="empty">لا توجد خطة فعالة لهذا الطالب.</div></div>`;
  let rows=plans.map(plan=>{let progress=smartPlanProgress(plan,student.id,date),a=progress.assignment,week=smartPlanWeekRequirement(plan,progress,date),review=plan.plan_type==='review'?smartPlanReviewSuggestions(student,date,plan):null,next=smartPlanNextDuty(plan,student,date),done=Number(progress.completedToday||0),required=Number(progress.dailyTarget??a.pages??0),remainingToday=Math.max(0,required-done),extra=Math.max(0,done-required),direction=plan.settings?.route_direction||plan.settings?.memorization_direction,last=smartPlanLastRecitationHtml(student,plan),nextText=next?`${next.date} · ${smartPlanAssignmentLabel(next.progress.assignment)}`:'لا يوجد مقرر تالٍ داخل هذه الخطة';let pause=progress.pauseReason==='sard_week'?'<div class="smart-pause">🔁 أسبوع السرد: الحفظ الجديد متوقف مؤقتاً ويستأنف تلقائياً بعد نهاية الأسبوع.</div>':'';return `<div class="smart-plan-track ${progress.health}"><div class="smart-track-title"><div><b>${esc(plan.title||smartPlanTypeAr[plan.plan_type])}</b><small>${smartPlanTypeAr[plan.plan_type]} · ${smartPlanPlanRangeText(plan)}${direction?` · ${esc(smartPlanDirectionAr[direction]||'')}`:''}</small></div>${smartPlanHealthBadge(progress)}</div>${smartPlanProgressBar(progress)}<div class="smart-kpis v5"><span><b>${fmt(required)}</b>🎯 مطلوب اليوم</span><span><b>${fmt(done)}</b>✅ المنجز اليوم</span><span><b>${fmt(remainingToday)}</b>⏳ المتبقي اليوم</span><span><b>${extra?`+${fmt(extra)}`:progress.aheadBy?`+${fmt(progress.aheadBy)}`:'0'}</b>📈 التقدم</span></div><div class="smart-today"><b>${smartPlanAssignmentLabel(a)}</b><span>هذا الأسبوع: ${fmt(week.amount)} ص · ${smartPlanRangeText(week.startPage,week.endPage)}</span>${a.blockedByRetry?'<span>آخر تسميع يحتاج إعادة؛ يعاد المقدار السابق فقط، و«جيد» لا يوقف الخطة.</span>':''}${review?`<span>قريب: ${smartPlanRangesText(review.nearRanges)}${review.farDue?` · بعيد: ${smartPlanRangesText(review.farRanges)}`:''}</span>`:''}</div>${pause}${last}<div class="smart-next-duty"><b>➡️ المقرر القادم</b><span>${esc(nextText)}</span></div>${smartPlanWhyHtml(progress)}${plan.plan_type==='sard'&&plan.settings?.intensive_week_from?`<div class="smart-sard-week">🔁 أسبوع سرد: ${plan.settings.intensive_week_from} → ${plan.settings.intensive_week_to} · ${fmt(plan.settings.intensive_daily_pages||7)} ص يومياً</div>`:''}${roleCanManage()?`<div class="plan-card-actions"><button class="mini" onclick="openPlan('${student.id}','${plan.id}')">تعديل</button><button class="mini red" onclick="archiveSmartPlan('${plan.id}')">أرشفة</button></div>`:''}</div>`}).join('');
  return `<div class="card smart-student-plan" data-smart-plan-student-name="${esc(normalizeNameJs(student.full_name))}" style="${smartPlanSearchMatchesStudent(student)?'':'display:none'}"><div class="section-head"><h3>الخطة الذكية · ${esc(student.full_name)}</h3>${roleCanManage()?`<button class="mini" onclick="openPlan('${student.id}')">+ مسار</button>`:''}</div>${rows}</div>`
}

function filterSmartPlanDashboard(v=''){state.smartPlanSearch=v;let q=normalizeNameJs(v),n=0,noPlanVisible=0;$$('[data-smart-plan-student-name]').forEach(card=>{let show=!q||String(card.dataset.smartPlanStudentName||'').includes(q);card.style.display=show?'':'none';if(show){n++;if(card.classList.contains('smart-no-plan-row'))noPlanVisible++}});let count=$('#smartPlanVisibleCount');if(count)count.textContent=n;let empty=$('#smartPlanSearchEmpty');if(empty)empty.classList.toggle('hidden',n>0);let noPlan=$('#smartPlanNoPlanDetails');if(noPlan&&q&&noPlanVisible)noPlan.open=true}
function smartPlanSearchMatchesStudent(student){let q=normalizeNameJs(state.smartPlanSearch||'');return !q||normalizeNameJs(student?.full_name||'').includes(q)}

function smartPlanReportRows(){
  let result=[];
  for(let student of activeStudents())for(let plan of effectiveSmartPlans(student)){if(state.smartPlanHalaqa!=='all'&&student.halaqa_id!==state.smartPlanHalaqa)continue;if(!smartPlanSearchMatchesStudent(student))continue;result.push({student,plan,progress:smartPlanProgress(plan,student.id)})}
  return result
}
function smartPlanReportsHtml(){
  let rows=smartPlanReportRows(),best=[...rows].sort((a,b)=>b.progress.percentage-a.progress.percentage).slice(0,8),delayed=rows.filter(x=>x.progress.health!=='green').sort((a,b)=>a.progress.percentage-b.progress.percentage),halaqas=state.halaqas.map(h=>{let r=rows.filter(x=>x.student.halaqa_id===h.id),target=r.reduce((s,x)=>s+Number(x.plan.target_pages||0),0),done=r.reduce((s,x)=>s+x.progress.completed,0);return {h,r,target,done,pct:target?done/target*100:0}}).filter(x=>x.r.length);let byType=Object.keys(smartPlanTypeAr).map(type=>{let r=rows.filter(x=>x.plan.plan_type===type);return {type,planned:r.reduce((s,x)=>s+x.progress.plannedByToday,0),done:r.reduce((s,x)=>s+x.progress.completed,0)}}).filter(x=>x.planned||x.done);
  return `<div class="smart-report-grid"><div class="card"><h3>أفضل التزام</h3>${best.map((x,i)=>`<div class="smart-report-row"><b>${i+1}. ${esc(x.student.full_name)}</b><span>${fmt(x.progress.percentage)}%</span></div>`).join('')||'<div class="empty">لا توجد بيانات.</div>'}</div><div class="card"><h3>الطلاب المتأخرون</h3>${delayed.map(x=>`<div class="smart-report-row"><span><b>${esc(x.student.full_name)}</b><small>${x.progress.consecutiveMissed} أيام متتالية · ${smartPlanTypeAr[x.plan.plan_type]}</small></span>${smartPlanHealthBadge(x.progress)}</div>`).join('')||'<div class="empty">كل الخطط ضمن المسار السليم.</div>'}</div></div><div class="card"><h3>نسبة إنجاز الحلقات</h3>${halaqas.map(x=>`<div class="smart-halaqa-report"><div><b>${esc(x.h.name)}</b><span>${x.r.length} مسار فعال</span></div><div class="smart-progress-track"><i style="width:${Math.min(100,x.pct)}%"></i></div><b>${fmt(x.pct)}%</b></div>`).join('')||'<div class="empty">لا توجد خطط.</div>'}</div><div class="card"><h3>المخطط مقابل المنجز حتى اليوم</h3><div class="smart-compare">${byType.map(x=>`<div><b>${smartPlanTypeAr[x.type]}</b><span>المخطط ${fmt(x.planned)} ص</span><i style="--ratio:${Math.min(100,x.planned?x.done/x.planned*100:0)}%"></i><strong>${fmt(x.done)} منجز</strong></div>`).join('')}</div></div>`
}

function smartPlanAutomationNotices(){let rows=(state.smartPlanEvents||[]).filter(x=>x.event_type==='auto_extension').slice(0,4);if(!rows.length)return '';return `<div class="smart-automation-notices"><b>تنبيهات المحرك الذكي</b>${rows.map(event=>{let plan=state.smartPlans.find(x=>x.id===event.plan_id),student=state.students.find(x=>x.id===event.student_id),payload=event.payload||{};return `<span>تم تمديد «${esc(plan?.title||'الخطة')}» للطالب ${esc(student?.full_name||'—')} من ${esc(payload.old_end_date||'—')} إلى ${esc(payload.new_end_date||'—')} لأن العجز تجاوز سقف التعويض الآمن.</span>`}).join('')}</div>`}

