function restoreSmartPlan(id){if(!roleCanManage())return;let plan=state.smartPlans.find(x=>x.id===id&&x.status==='archived');if(!plan)return toast('الخطة المؤرشفة غير موجودة');if(!confirm(`استعادة خطة «${plan.title}» وإعادتها إلى الخطط النشطة؟`))return;saveSmartPlanLocal({...plan,status:'active',updated_at:new Date().toISOString()});toast('تمت استعادة الخطة وستتزامن تلقائياً');render()}
function deleteArchivedSmartPlan(id){if(!roleCanManage())return;let plan=state.smartPlans.find(x=>x.id===id&&x.status==='archived');if(!plan)return toast('الخطة المؤرشفة غير موجودة');if(!confirm(`حذف خطة «${plan.title}» نهائياً من قاعدة البيانات؟\nلن تُحذف تسميعات الطالب أو الجلسات التاريخية.`))return;if(!confirm('تأكيد أخير: حذف الخطة نفسها نهائي ولا يمكن استرجاعها. متابعة؟'))return;state.smartPlans=state.smartPlans.filter(x=>x.id!==id);state.smartPlanEvents=state.smartPlanEvents.filter(x=>x.plan_id!==id);let queue=typeof readOfflineQueue==='function'?readOfflineQueue():[];if(Array.isArray(queue)&&typeof writeOfflineQueue==='function'){queue=queue.filter(op=>!(op.type==='smart_plan_upsert'&&String(op.payload?.row?.id||'')===String(id))&&!(op.type==='smart_plan_event'&&String(op.payload?.plan_id||'')===String(id))&&!(op.type==='smart_plan_delete'&&String(op.payload?.id||'')===String(id)));writeOfflineQueue(queue)}enqueueOffline({type:'smart_plan_delete',key:`smart-plan-delete:${id}`,dedupeKey:`smart-plan-delete:${id}`,payload:{id}});cacheSnapshot();toast(navigator.onLine?'تم طلب الحذف النهائي وستُحدّث المزامنة الآن':'تم حذفها من الجهاز وسيكتمل الحذف النهائي عند عودة الإنترنت');render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),30)}
function plansPage(){
  beginSmartPlanRenderMemo();
  try{
    if(state.smartPlansAvailable===false)return `<div class="hero"><h2>الخطط الذكية</h2><p>المحرك جاهز، وتبقى تهيئة جدولي الخطط والأحداث على Supabase.</p></div><div class="notice"><b>طبّق ترحيل قاعدة البيانات أولاً:</b><br>supabase/migrations/20260831_v217_smart_plan_categories_admin_delete.sql${state.smartPlanError?`<br><span class="muted">${esc(state.smartPlanError)}</span>`:''}</div>`;
    let students=activeStudents().filter(x=>state.smartPlanHalaqa==='all'||x.halaqa_id===state.smartPlanHalaqa),visibleStudents=students.filter(smartPlanSearchMatchesStudent),rows=smartPlanReportRows(),studentsWithPlans=new Set(rows.map(x=>String(x.student.id))),planStudents=roleCanManage()?students.filter(x=>studentsWithPlans.has(String(x.id))):students,noPlanStudents=roleCanManage()?students.filter(x=>!studentsWithPlans.has(String(x.id))):[],avg=rows.length?rows.reduce((s,x)=>s+x.progress.percentage,0)/rows.length:0,behind=rows.filter(x=>x.progress.health!=='green').length,groups=(state.smartPlans||[]).filter(x=>['halaqa','category'].includes(x.scope_type)&&x.status!=='archived'&&(state.smartPlanHalaqa==='all'||x.halaqa_id===state.smartPlanHalaqa));
    let controls=roleCanManage()?`<div class="smart-plan-tabs"><button class="${state.smartPlanTab==='dashboard'?'active':''}" onclick="state.smartPlanTab='dashboard';render()">لوحة الخطط</button><button class="${state.smartPlanTab==='reports'?'active':''}" onclick="state.smartPlanTab='reports';render()">تقارير الخطط</button><button class="${state.smartPlanTab==='archived'?'active':''}" onclick="state.smartPlanTab='archived';render()">الخطط المؤرشفة</button></div><div class="smart-plan-filter-grid"><label class="field smart-plan-filter"><span>الحلقة</span><select onchange="state.smartPlanHalaqa=this.value;render()"><option value="all">كل الحلقات</option>${state.halaqas.map(h=>`<option value="${h.id}" ${state.smartPlanHalaqa===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label><label class="field smart-plan-filter"><span>بحث باسم الطالب</span><input class="input" type="search" value="${esc(state.smartPlanSearch)}" placeholder="اكتب اسم الطالب" oninput="filterSmartPlanDashboard(this.value)"></label></div>`:'';
    if(state.smartPlanTab==='reports'&&roleCanManage())return `<div class="hero"><h2>تقارير الخطط الذكية</h2><p>أفضل التزام، حالات التعثر، إنجاز الحلقات، والمخطط مقابل المنجز الفعلي.</p></div>${controls}${smartPlanAutomationNotices()}${smartPlanReportsHtml()}`;
    if(state.smartPlanTab==='archived'&&roleCanManage())return `<div class="hero"><h2>الخطط المؤرشفة</h2><p>سجل الخطط القديمة محفوظ للمراجعة. يمكنك استعادة الخطة أو حذفها نهائياً دون حذف تسميعات الطالب التاريخية.</p></div>${controls}${smartArchivedPlansHtml()}`;
    let groupHtml=groups.length?`<div class="section-head"><h3>الخطط الجماعية</h3></div>${groups.map(plan=>{let members=activeSmartPlanStudents(plan),progress=members.map(s=>smartPlanProgress(plan,s.id)),mean=progress.length?progress.reduce((a,x)=>a+x.percentage,0)/progress.length:0;let scopeLabel=plan.scope_type==='category'?`فئة: ${esc(state.categories.find(x=>x.id===plan.category_id)?.name||'—')}`:'الحلقة كلها';return `<div class="card smart-group-plan"><div class="row"><div class="avatar">ح</div><div class="grow"><b>${esc(plan.title)}</b><div class="muted">${esc(state.halaqas.find(x=>x.id===plan.halaqa_id)?.name||'')} · ${scopeLabel} · ${smartPlanTypeAr[plan.plan_type]} · ${members.length} طالب</div></div><span class="badge blue">${plan.scope_type==='category'?'فئة':'جماعية'}</span></div><div class="smart-kpis"><span><b>${fmt(plan.target_pages)}</b>الهدف/طالب</span><span><b>${fmt(mean)}%</b>متوسط الإنجاز</span><span><b>${progress.filter(x=>x.health==='red').length}</b>خطر تعثر</span><span><b>${plan.end_date}</b>النهاية</span></div><div class="plan-card-actions"><button class="mini" onclick="openPlan('','${plan.id}')">تعديل الخطة</button><button class="mini" onclick="openSmartPlanOverride('${plan.id}')">تخصيص لطالب</button><button class="mini red" onclick="archiveSmartPlan('${plan.id}')">أرشفة</button></div></div>`}).join('')}`:'';
    let noPlanHtml=roleCanManage()&&noPlanStudents.length?`<details id="smartPlanNoPlanDetails" class="card smart-no-plan-list" ${state.smartPlanSearch?'open':''}><summary><b>طلاب بلا خطة فعالة</b><span>${noPlanStudents.length}</span></summary><div>${noPlanStudents.map(student=>`<div class="smart-no-plan-row" data-smart-plan-student-name="${esc(normalizeNameJs(student.full_name))}" style="${smartPlanSearchMatchesStudent(student)?'':'display:none'}"><span class="grow"><b>${esc(student.full_name)}</b><small>${esc(state.halaqas.find(h=>h.id===student.halaqa_id)?.name||'')}</small></span><button class="mini" onclick="openPlan('${student.id}')">+ إنشاء خطة</button></div>`).join('')}</div></details>`:'';
    return `<div class="hero"><h2>الخطط الذكية</h2><p>فتح أسرع، ومقرر يومي شخصي محسوب بالأسطر والآيات حسب هدف كل طالب.</p></div>${controls}${roleCanManage()?smartPlanAutomationNotices():''}<div class="grid stats">${stat('المسارات الفعالة',rows.length)}${stat(state.profile?.role==='guardian'&&rows.length===1?'إنجاز الخطة الحالية':'متوسط الإنجاز',fmt(avg)+'%')}${stat('بحاجة متابعة',behind)}${stat('طلاب بلا خطة',noPlanStudents.length)}</div>${groupHtml}<div class="section-head"><h3>${state.profile?.role==='guardian'?'خطط أبنائي':'خطط الطلاب'}</h3>${roleCanManage()?'<button class="btn btn-primary" onclick="openPlan()">+ خطة ذكية</button>':''}</div><div class="muted smart-plan-result-count">المعروض: <span id="smartPlanVisibleCount">${visibleStudents.length}</span> من ${students.length}</div>${planStudents.map(student=>smartPlanStudentPanel(student,today(),false)).join('')}${noPlanHtml}${!students.length?'<div class="empty">لا يوجد طلاب في هذا النطاق.</div>':''}<div id="smartPlanSearchEmpty" class="empty ${visibleStudents.length?'hidden':''}">لا يوجد طالب مطابق للبحث.</div>`
  }finally{endSmartPlanRenderMemo()}
}

function smartPlanScopeStudentsFromForm(){let scope=$('#spScope').value,hid=$('#spHalaqa').value;if(scope==='student'){let st=state.students.find(x=>x.id===$('#spStudent').value);return st?[st]:[]}if(scope==='category'){let cid=$('#spCategory').value;return activeStudents().filter(x=>x.halaqa_id===hid&&x.category_id===cid)}return activeStudents().filter(x=>x.halaqa_id===hid)}
function updateSmartPlanScope(){let scope=$('#spScope').value;$('#spStudentField').classList.toggle('hidden',scope!=='student');$('#spCategoryField').classList.toggle('hidden',scope!=='category');$('#spStudent').required=scope==='student';$('#spCategory').required=scope==='category';updateSmartPlanHifzStartMode();previewSmartPlanEstimate()}
