function updateSmartPlanStudents(){let hid=$('#spHalaqa').value,current=$('#spStudent').value,q=normalizeNameJs($('#spStudentSearch')?.value||''),all=activeStudents().filter(x=>x.halaqa_id===hid),rows=q?all.filter(x=>normalizeNameJs(x.full_name).includes(q)):all;state.smartPlanStudentSearch=$('#spStudentSearch')?.value||'';$('#spStudent').innerHTML=rows.map(x=>`<option value="${x.id}">${esc(x.full_name)}</option>`).join('');if(rows.some(x=>x.id===current))$('#spStudent').value=current;else if(rows[0])$('#spStudent').value=rows[0].id;let hint=$('#spStudentSearchHint');if(hint)hint.textContent=`المعروض ${rows.length} من ${all.length}`;refreshSmartPlanSuggestedStart()}
