function archiveSmartPlan(id){if(!roleCanManage())return;let plan=state.smartPlans.find(x=>x.id===id);if(!plan)return;if(!confirm(`أرشفة خطة «${plan.title}»؟\nلن تُحذف سجلات التسميع أو أحداث الخطة.`))return;saveSmartPlanLocal({...plan,status:'archived',updated_at:new Date().toISOString()});render()}
function approveSmartPlanMilestone(planId,studentId,key){let plan=state.smartPlans.find(x=>x.id===planId);if(!plan||!roleCanManage())return;recordSmartPlanEvent(planId,studentId,'milestone_approved',{milestone_key:key,approved_at:new Date().toISOString()});toast('تم اعتماد الاختبار وفتح المقرر التالي');render();if(state.sessionView)setTimeout(()=>injectSmartPlanSessionWidgets(state.sessionView),0)}

function smartPlanForSession(student,date,sessionType='tasmee'){
  if(sessionType==='lesson')return null;let plans=effectiveSmartPlans(student,date),wanted=sessionType==='review'?'review':sessionType==='sard'?'sard':sessionType==='test'?'hifz':student.track_code==='tathbit'?'tathbit':'hifz',plan=plans.find(x=>x.plan_type===wanted)||plans[0];if(!plan)return null;let progress=smartPlanProgress(plan,student.id,date);return {plan,progress,review:plan.plan_type==='review'?smartPlanReviewSuggestions(student,date,plan):null}
}
function smartPlanDailyAchieved(plan,studentId,date){return Number(smartPlanProgress(plan,studentId,date).completedToday||0)}
function smartPlanSessionWidget(student,session){let item=smartPlanForSession(student,session.session_date,session.session_type);if(!item)return '';let {plan,progress,review}=item,a=progress.assignment,done=smartPlanDailyAchieved(plan,student.id,session.session_date),required=review?(review.nearRanges.reduce((s,x)=>s+x.end-x.start+1,0)+review.farRanges.reduce((s,x)=>s+x.end-x.start+1,0)):Number((progress.dailyTarget??a.pages)||0),remaining=Math.max(0,required-done),extra=Math.max(0,done-required),next=smartPlanNextDuty(plan,student,session.session_date),retryNote=a.kind==='tathbit'?'<small>آخر تسميع يحتاج إعادة؛ «جيد» لا يوقف الخطة.</small>':'';return `<div class="smart-session-plan ${progress.health}"><div><b>المقرر الذكي اليوم</b><span>${smartPlanAssignmentLabel(a)}</span>${retryNote}${progress.pauseReason==='sard_week'?'<small>أسبوع سرد: لا يوجد حفظ جديد اليوم.</small>':''}${review?`<small>قريب: ${smartPlanRangesText(review.nearRanges)}${review.farDue?` · بعيد: ${smartPlanRangesText(review.farRanges)}`:''}</small>`:''}</div><div class="smart-session-kpis"><span>مطلوب <b>${fmt(required)}</b></span><span>أنجز <b>${fmt(done)}</b></span><span>متبقي <b>${fmt(remaining)}</b></span>${extra?`<span>متقدم <b>+${fmt(extra)}</b></span>`:''}</div>${smartPlanLastRecitationHtml(student,plan)}${next?`<div class="smart-next-duty compact"><b>غداً/القادم</b><span>${esc(next.date)} · ${smartPlanAssignmentLabel(next.progress.assignment)}</span></div>`:''}<button class="mini" type="button" onclick="oneTapSmartPlanPrefill('${student.id}','${session.id}','${plan.id}')">تسميع المقرر اليومي</button>${a.milestone?`<button class="mini" type="button" onclick="approveSmartPlanMilestone('${plan.id}','${student.id}','${a.milestone.key}')">اعتماد ${esc(a.milestone.label)}</button>`:''}</div>`}
function injectSmartPlanSessionWidgets(sessionId){let session=state.sessions.find(x=>String(x.id)===String(sessionId));if(!session)return;for(let student of activeStudents().filter(x=>x.halaqa_id===session.halaqa_id)){let card=$(`#roster_${student.id}`);if(!card)continue;card.querySelector('.smart-session-plan')?.remove();let html=smartPlanSessionWidget(student,session);if(html)card.querySelector('.roster-recitations')?.insertAdjacentHTML('beforebegin',html)}}
const smartPlanBaseSessionRosterPage=sessionRosterPage;
sessionRosterPage=function(id){let html=smartPlanBaseSessionRosterPage(id);setTimeout(()=>injectSmartPlanSessionWidgets(id),0);return html};

function addSmartPlanPageRow(plan,kind,start,end,date){if(!start||!end)return null;addRecitationRow(kind);let row=$$('#recitationRows .rec-row').at(-1),id=row.dataset.id,modeButton=row.querySelectorAll('.seg button')[1];setRecMode(modeButton,'pages');$('#'+id+'PF').value=start;$('#'+id+'PT').value=end;row.dataset.startPage=start;row.dataset.endPage=end;row.dataset.pages=end-start+1;row.dataset.smartPlanId=plan.id;row.dataset.smartPlanType=plan.plan_type;row.dataset.smartPlanDate=date;row.querySelector('.rType').value=kind;calcRecRow(row);return row}
async function addSmartPlanAyahRow(plan,kind,segment,date){if(!segment?.surah||!segment?.startAyah||!segment?.endAyah)return null;addRecitationRow(kind);let row=$$('#recitationRows .rec-row').at(-1),id=row.dataset.id,modeButton=row.querySelectorAll('.seg button')[0];setRecMode(modeButton,'ayahs');$('#'+id+'SS').value=segment.surah;$('#'+id+'SA').value=segment.startAyah;$('#'+id+'ES').value=segment.surah;$('#'+id+'EA').value=segment.endAyah;if(typeof syncAyahPickerFromFields==='function')syncAyahPickerFromFields(id);row.dataset.smartPlanId=plan.id;row.dataset.smartPlanType=plan.plan_type;row.dataset.smartPlanDate=date;row.querySelector('.rType').value=kind;await calcRecRow(row);return row}
async function oneTapSmartPlanPrefill(studentId,sessionId,planId){let session=state.sessions.find(x=>String(x.id)===String(sessionId)),student=state.students.find(x=>x.id===studentId),rawPlan=state.smartPlans.find(x=>x.id===planId);if(!session||!student||!rawPlan)return toast('تعذر العثور على مقرر الخطة');let plan=materializeSmartPlan(rawPlan,student);if(!reportDlg.open)await openDailyForStudent(studentId,sessionId);let empty=$$('.rec-row').filter(r=>!r.dataset.dbId&&Number(r.dataset.pages||0)===0);empty.forEach(r=>r.remove());let progress=smartPlanProgress(rawPlan,studentId,session.session_date),a=progress.assignment,added=0;if(plan.plan_type==='review'){let review=smartPlanReviewSuggestions(student,session.session_date,plan);for(let range of review.nearRanges){addSmartPlanPageRow(plan,'review_near',range.start,range.end,session.session_date);added++}for(let range of review.farRanges){addSmartPlanPageRow(plan,'review_far',range.start,range.end,session.session_date);added++}}else if(['hifz','sard','tathbit'].includes(plan.plan_type)&&a.ayahSegments?.length&&!a.milestone){let kind=plan.plan_type==='sard'?'sard':plan.plan_type==='tathbit'?'review_far':a.kind==='hifz'?'new_hifz':'review_far';for(let segment of a.ayahSegments){await addSmartPlanAyahRow(plan,kind,segment,session.session_date);added++}}else{let kind=a.kind==='hifz'?'new_hifz':a.kind==='sard'?'sard':a.kind==='test'?'test':'review_far';if(a.retryRanges?.length){for(let range of a.retryRanges){addSmartPlanPageRow(plan,kind,range.start,range.end,session.session_date);added++}}else if(a.startPage&&a.endPage){addSmartPlanPageRow(plan,kind,a.startPage,a.endPage,session.session_date);added++}}if(!added){addRecitationRow(plan.plan_type==='sard'?'sard':plan.plan_type==='review'?'review_near':'new_hifz');toast('لا يوجد مقدار تلقائي اليوم؛ أضيف بند فارغ للتسجيل اليدوي')}else toast('تمت تعبئة المقرر اليومي من الخطة بالآيات المحددة')}

function injectSmartPlanReportStrip(studentId,sessionId){let student=state.students.find(x=>x.id===studentId),session=state.sessions.find(x=>String(x.id)===String(sessionId));if(!student||!session)return;$('#smartPlanReportStrip')?.remove();let item=smartPlanForSession(student,session.session_date,session.session_type);if(!item)return;let holder=document.createElement('div');holder.id='smartPlanReportStrip';holder.innerHTML=smartPlanSessionWidget(student,session);let anchor=$('#reportDlg .section-head');anchor?.insertAdjacentElement('beforebegin',holder)}
const smartPlanBaseOpenDailyForStudent=openDailyForStudent;
openDailyForStudent=async function(studentId,sessionId=null){await smartPlanBaseOpenDailyForStudent(studentId,sessionId);let actual=sessionId||$('#rpSession')?.value;injectSmartPlanReportStrip(studentId,actual)};

const smartPlanBaseGuardianHomePage=guardianHomePage;
guardianHomePage=function(){let html=smartPlanBaseGuardianHomePage();let panels=activeStudents().map(st=>`<div class="guardian-smart-summary">${smartPlanStudentPanel(st,today(),true)}</div>`).join('');return html.replace('<div class="actions">',`${panels}<div class="actions">`)};

const smartPlanBaseStudentProfile=studentProfile;
studentProfile=function(id){smartPlanBaseStudentProfile(id);let student=state.students.find(x=>x.id===id),content=$('#content');if(!student||!content)return;let panel=document.createElement('div');panel.innerHTML=smartPlanStudentPanel(student,today(),false);let back=content.querySelector('button.btn.btn-ghost:last-child');if(back)back.insertAdjacentElement('beforebegin',panel);else content.appendChild(panel)};

async function checkSmartPlanAlerts(){
  if(!roleCanManage()||!state.smartPlansAvailable||!navigator.onLine||typeof invokeNotify!=='function')return;let date=today(),tomorrow=smartPlansEngine.addDays(date,1),evening=new Date().getHours()>=17;
  for(let student of activeStudents()){
    for(let plan of effectiveSmartPlans(student,date)){let progress=smartPlanProgress(plan,student.id,date);if(progress.consecutiveMissed>=plan.delay_alert_days){await invokeNotify({action:'event_student',kind:'system',student_id:student.id,source_key:`smart-plan-delay:${plan.id}:${student.id}:${date}`,title:`تنبيه الخطة · ${student.full_name}`,body:`الخطة متأخرة ${progress.consecutiveMissed} أيام دوام. المتبقي ${fmt(progress.remaining)} صفحة، والحالة ${progress.healthLabel}.`,deep_link:`student:${student.id}`,data:{smart_plan_id:plan.id,health:progress.health,missed_days:progress.consecutiveMissed}},{silent:true})}}
    if(evening){let next=smartPlanForSession(student,tomorrow,'tasmee');if(next?.plan?.home_prep_push&&next.progress.assignment.startPage){let a=next.progress.assignment;await invokeNotify({action:'event_student',kind:'system',student_id:student.id,source_key:`smart-plan-prep:${next.plan.id}:${student.id}:${tomorrow}`,title:`تحضير الغد · ${student.full_name}`,body:`مطلوب غداً ${smartPlanAssignmentLabel(a)}.`,deep_link:`student:${student.id}`,data:{smart_plan_id:next.plan.id,plan_date:tomorrow,start_page:a.startPage,end_page:a.endPage}},{silent:true})}}
  }
}
